// This file is generated by AI.

// 确认框请求的字段口径: 提示类消息 (`requestAlert`) 常常是「对象 + 多行错误原文」,
// 必须走正文的 `detail` —— 标题下那行 `description` 是 12px 副标题, 既不保留换行,
// 也没有给长路径留断行策略 (见 2026-11 的「删除导出文件」确认框)。

import { afterEach, describe, expect, it, vi } from 'vitest';

import { pendingConfirm, requestAlert, requestConfirm, resolveConfirm } from '../src/confirm';

afterEach(() => {
  resolveConfirm(false);
});

describe('确认框请求', () => {
  it('提示把消息放进正文 detail, 不占副标题', () => {
    const message = '目标目录：C:\\Users\\a\\b\n\n错误原文：找不到文件';
    requestAlert('导入失败', message);
    const request = pendingConfirm();
    expect(request?.detail).toBe(message);
    expect(request?.description).toBeUndefined();
    expect(request?.info).toBe(true);
    expect(request?.confirmLabel).toBe('知道了');
  });

  it('普通确认仍然用 description 说明后果', () => {
    requestConfirm({ title: '删除导出的文件？', description: '文件会移到系统回收站。', action: () => {} });
    expect(pendingConfirm()?.description).toBe('文件会移到系统回收站。');
    expect(pendingConfirm()?.detail).toBeUndefined();
  });

  it('确认才执行动作, 取消不执行', () => {
    const run = vi.fn();
    requestConfirm({ title: 't', action: run });
    resolveConfirm(true);
    expect(run).toHaveBeenCalledTimes(1);

    requestConfirm({ title: 't', action: run });
    resolveConfirm(false);
    expect(run).toHaveBeenCalledTimes(1);
    expect(pendingConfirm()).toBeNull();
  });
});
